      'Bricht de Fortschritt vo eme ISO-Managementsystem (27001/9001/42001): Status pro Massnahme und e abgleiteti Fortschrittsübersicht. Standardmässig us; aktivier d Erwyterig, zum de Slide-Typ bruuche.',
