  '1 slide achtergehouden door haar TLP': '1 Slide wäg sim TLP zrugghalte',
  'slides achtergehouden door hun TLP': 'Slides wäg ihrem TLP zrugghalte',
  'Deze slides gaan niet mee bij presenteren, exporteren of in het pakket. Verhoog het TLP-niveau van de presentatie bij Presentatie-info om ze mee te nemen.':
      'Die Slides chömed bim Präsentiere, Exportiere und im Paket nöd mit. Erhöh under Präsentationsinfo s TLP-Niveau vo de Präsentation, zum si mitznäh.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Alli Slides sind wäg ihrer TLP-Klassifizierig zrugghalte, drum git\'s nüt zum zeige.',
  'Alle slides zijn achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Alli Slides sind wäg ihrer TLP-Klassifizierig zrugghalte, drum git\'s nüt zum exportiere.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te tonen.':
      'Alli Slides sind übersprunge oder wäg ihrer TLP-Klassifizierig zrugghalte, drum git\'s nüt zum zeige.',
  'Alle slides zijn overgeslagen of achtergehouden door hun TLP-classificatie — niets om te exporteren.':
      'Alli Slides sind übersprunge oder wäg ihrer TLP-Klassifizierig zrugghalte, drum git\'s nüt zum exportiere.',
  'Grafiekcijfers zijn niet opgeslagen — ze staan alleen nog in dit venster:':
      'D Diagrammzahle sind nöd gspeicheret worde — sie stönd nu no i dem Fänschter:',
  'In de browser is er geen crashherstel: sluit je dit tabblad, dan is niet-opgeslagen werk weg. Sla je presentatie zelf op.':
      'Im Browser git\'s kei Absturz-Wiederherstellig: wänn du das Tab zuemachsch, isch nöd gspeicherti Arbet ewäg. Speicher dini Präsentation sälber.',
  '•  De lokale CVE-database (je start de download zelf): OciDeck haalt de bulkgegevens op via api.github.com en het releasebestand waar dat adres naar wijst.':
      '•  D lokal CVE-Datebank (de Download startisch du sälber): OciDeck holt d Massedate über api.github.com und d Release-Datei, wo die Adrässe druf zeigt.',
  '•  CVE opzoeken (staat standaard uit): staat het aan, dan gaat je zoekterm naar de ingestelde CVE-spiegel en, als die niets vindt, naar de Europese database van ENISA en naar MITRE.':
      '•  CVE sueche (isch standardmässig us): wenn s aa isch, gaht dis Suechwort a de iigstellt CVE-Spiegel und, wenn dä nüt findt, a d europäisch Datebank vo de ENISA und a MITRE.',
  '•  Een ingesloten YouTube- of Vimeo-video laadt de speler bij die dienst.':
      '•  Es iibunde YouTube- oder Vimeo-Video ladt de Player bi dem Dienscht.',
  '•  In de browser: weigert de browser een adres rechtstreeks op te halen, dan probeert OciDeck het via de server waar de app vandaan komt; dat adres komt dan bij die server terecht.':
      '•  Im Browser: wenn de Browser en Adrässe nöd direkt abhole will, probiert s OciDeck über de Server, wo d App härchunt; die Adrässe chunt denn zu dem Server.',
  'Intrekken is niet vastgelegd. Bij de volgende start geldt uw toestemming weer.':
      'De Widerruef isch nöd gspeicheret worde. Bim nöchschte Schtart gilt dini Zueschtimmig wider.',
  'Een tussenkop die een nieuw deel van de presentatie aankondigt. Houd het kort. Voeg via de afbeeldingsbibliotheek een achtergrondbeeld toe.':
      'E Zwüschetitel wo en neue Teil vo de Präsentation aakündigt. Halt en churz. Über d Bildbibliothek chasch es Hintergrundbild derzuetue.',
  'Bronnen doorzoeken…': 'Quelle wärde durchsuecht…',
  'Niet doorzocht': 'Nöd durchsuecht',
  'Deze controle draait niet in de webversie: gezichtsherkenning vergt een systeembibliotheek die de browser niet heeft. Gebruik de desktopversie om afbeeldingen op gezichten na te kijken.':
      'Die Prüefig lauft i de Web-Version nöd: Gsichtserkennig bruucht e Systembibliothek, wo de Browser nöd het. Nimm d Desktop-Version, zum Bilder uf Gsichter z prüefe.',
  'Het token heeft lees- en schrijfrechten op de repository nodig. Gitea en Forgejo kennen geen server-side zoeken; OciDeck zoekt lokaal.':
      'S Token bruucht Läse- und Schriibrächt fürs Repository. Gitea und Forgejo hei kei serversitigi Suech; OciDeck suecht lokal.',
  'Het token heeft de repo-scope nodig (of fijnmazig: Contents lezen en schrijven).':
      'S Token bruucht de repo-Scope (oder fiin: Contents läse und schriibe).',
  'Het token heeft read_repository, write_repository en read_api nodig. Server-side zoeken vereist Advanced- of Exact Search.':
      'S Token bruucht read_repository, write_repository und read_api. D serversitigi Suech verlangt Advanced oder Exact Search.',
  'Snelle server-zoekopdracht — door indexeringsvertraging kan een net gewijzigd deck ontbreken.':
      'Schnälli serversitigi Suech — wäge Indexierigsverzögerig cha nes grad gänderets Deck fähle.',
  'Media blijft niet bewaard in een los .md-bestand':
      'Medie bliibe in ere blosse .md-Datei nöd erhalte',
  'Afbeeldingen, video en audio die je in dit tabblad koos, leven alleen in het geheugen. Een los .md-bestand bewaart ze niet — bij heropenen zijn ze weg. Exporteer als .ocideck-pakket om het beeld mee te nemen.':
      'Bilder, Video und Audio, wo du i dem Tab gwählt hesch, läbe nume im Arbetsspeicher. E blossi .md-Datei behaltet sie nöd — bim neu Uufmache sind sie ewäg. Exportier als .ocideck-Paket, zum d Medie mitnäh.',
